function UIMain_JumpBtn:__init()
    self.controller = nil
end


function UIMain_JumpBtn:__delete()
end



function UIMain_JumpBtn:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end


function UIMain_JumpBtn:Start()
    KTool.SetActive(self.controller.gameObject, true)

    self.jumpButton    = KTool.GetComponent( self.controller.gameObject, typeof(Button) )
    self.jumpAnimation = KTool.GetComponent( self.controller.gameObject, typeof(Animation) )
    assert( self.jumpButton and self.jumpAnimation )
        
    self.jumpAnimation:Play( ButtonIdle )

    self.jumpButton.onClick:AddListener( Bind(self, self.OnPress) )
end




function UIMain_JumpBtn:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

